INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtq6e80005wwk5huy0e87z', 'Introduction to Veterinary Anatomy', 'Definition, scope, history and branches of anatomy. Comparative anatomy across domestic species. Anatomical terminology, planes, directions and body cavities used in veterinary science.', 1, NULL, NULL, NULL, 'cmsqtq66d0004wwk5lkehpux8', '2026-08-13T01:12:46.304Z', '2026-08-13T01:12:46.304Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtq6lr0006wwk59q4o9ony', 'General Histology and Tissue Types', 'Epithelial, connective, muscular and nervous tissue types. Microscopic structure of tissues, staining techniques and tissue identification methods.', 1, NULL, NULL, NULL, 'cmsqtq66d0004wwk5lkehpux8', '2026-08-13T01:12:46.575Z', '2026-08-13T01:12:46.575Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtq6t70007wwk5189pm2bj', 'Cell Biology and Ultrastructure', 'Cell structure, organelles, cell division and cell cycle. Membrane transport, intracellular signalling and cellular specialisation in veterinary species.', 1, NULL, NULL, NULL, 'cmsqtq66d0004wwk5lkehpux8', '2026-08-13T01:12:46.843Z', '2026-08-13T01:12:46.843Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtq70m0008wwk5q4gw2ye2', 'Skeletal System – Axial Skeleton', 'Bones of the skull, vertebral column, ribs and sternum across domestic animals. Osteology, bone development and species-specific skeletal features.', 2, NULL, NULL, NULL, 'cmsqtq66d0004wwk5lkehpux8', '2026-08-13T01:12:47.110Z', '2026-08-13T01:12:47.110Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtq77y0009wwk5riarixyh', 'Skeletal System – Appendicular Skeleton', 'Bones of the fore limb and hind limb. Joint types, arthrology and synovial joint structures. Comparative limb anatomy in quadrupeds.', 2, NULL, NULL, NULL, 'cmsqtq66d0004wwk5lkehpux8', '2026-08-13T01:12:47.374Z', '2026-08-13T01:12:47.374Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtq7fd000awwk5guwoze9e', 'Myology – Muscles of the Body', 'Major skeletal muscles, their origins, insertions and actions. Muscular compartments and fascial planes. Muscle fibre types and functional anatomy.', 2, NULL, NULL, NULL, 'cmsqtq66d0004wwk5lkehpux8', '2026-08-13T01:12:47.641Z', '2026-08-13T01:12:47.641Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtq7mp000bwwk5vy91jqy5', 'Integumentary System', 'Skin, hair, horns, hooves, claws and glands. Integumentary structures in different species and their functional significance.', 2, NULL, NULL, NULL, 'cmsqtq66d0004wwk5lkehpux8', '2026-08-13T01:12:47.905Z', '2026-08-13T01:12:47.905Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtq7u2000cwwk5v2tfy5oc', 'Digestive System Anatomy', 'Comparative anatomy of the gastrointestinal tract in monogastric and ruminant animals. Mouth, pharynx, oesophagus, stomach, intestines and associated glands.', 3, NULL, NULL, NULL, 'cmsqtq66d0004wwk5lkehpux8', '2026-08-13T01:12:48.170Z', '2026-08-13T01:12:48.170Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtq81g000dwwk54v39a7hy', 'Respiratory System Anatomy', 'Nasal cavity, larynx, trachea, bronchi and lungs. Comparative respiratory anatomy across species, including avian air sac system.', 3, NULL, NULL, NULL, 'cmsqtq66d0004wwk5lkehpux8', '2026-08-13T01:12:48.436Z', '2026-08-13T01:12:48.436Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtq88x000ewwk5latk1kk6', 'Splanchnology – Associated Organs', 'Liver, spleen, pancreas and mesentery. Peritoneal cavity, omentum and peritoneal reflections.', 3, NULL, NULL, NULL, 'cmsqtq66d0004wwk5lkehpux8', '2026-08-13T01:12:48.705Z', '2026-08-13T01:12:48.705Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtq8ga000fwwk58bhrpwdu', 'Reproductive System Anatomy', 'Male and female reproductive organs across domestic species. Testes, epididymis, vas deferens, penis, ovaries, oviducts, uterus, vagina and external genitalia.', 4, NULL, NULL, NULL, 'cmsqtq66d0004wwk5lkehpux8', '2026-08-13T01:12:48.970Z', '2026-08-13T01:12:48.970Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtq8no000gwwk5jxsos5n3', 'Nervous System – Central Nervous System', 'Brain and spinal cord anatomy. Cerebrum, cerebellum, brainstem, meninges, ventricles and spinal cord segments.', 4, NULL, NULL, NULL, 'cmsqtq66d0004wwk5lkehpux8', '2026-08-13T01:12:49.236Z', '2026-08-13T01:12:49.236Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtq8v3000hwwk50rs4q16n', 'Nervous System – Peripheral Nervous System', 'Cranial nerves, spinal nerves and autonomic nervous system. Ganglia, nerve plexuses and peripheral nerve distribution.', 4, NULL, NULL, NULL, 'cmsqtq66d0004wwk5lkehpux8', '2026-08-13T01:12:49.503Z', '2026-08-13T01:12:49.503Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtq92i000iwwk5fxa1mn6v', 'Cardiovascular System', 'Heart anatomy, chambers, valves and conduction system. Great vessels, arterial and venous systems across species.', 4, NULL, NULL, NULL, 'cmsqtq66d0004wwk5lkehpux8', '2026-08-13T01:12:49.770Z', '2026-08-13T01:12:49.770Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtq9hc000kwwk5vhxhgr1p', 'Introduction to Physiology and Cell Physiology', 'Principles of homeostasis, cell membrane potentials, ion channels and nerve impulse generation. Resting membrane potential and action potential in excitable tissues.', 1, NULL, NULL, NULL, 'cmsqtq99x000jwwk51tnfs88r', '2026-08-13T01:12:50.304Z', '2026-08-13T01:12:50.304Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtq9oq000lwwk5cdv3mlug', 'Body Fluids and Composition', 'Body water distribution, intracellular and extracellular fluid compartments. Osmolality, tonicity, electrolyte balance and acid-base physiology.', 1, NULL, NULL, NULL, 'cmsqtq99x000jwwk51tnfs88r', '2026-08-13T01:12:50.570Z', '2026-08-13T01:12:50.570Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtq9w3000mwwk5toj2tvgc', 'Haematology – Blood and its Components', 'Plasma composition, erythrocytes, leucocytes and platelets. Haemoglobin, haematocrit, erythropoiesis and blood typing in domestic animals.', 1, NULL, NULL, NULL, 'cmsqtq99x000jwwk51tnfs88r', '2026-08-13T01:12:50.835Z', '2026-08-13T01:12:50.835Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqa3j000nwwk5408gj8zq', 'Digestive Physiology', 'Ingestion, motility, secretion, digestion and absorption across the gastrointestinal tract. Ruminant fermentation, monogastric digestion and species variations.', 2, NULL, NULL, NULL, 'cmsqtq99x000jwwk51tnfs88r', '2026-08-13T01:12:51.103Z', '2026-08-13T01:12:51.103Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqaaw000owwk56jay5uo7', 'Respiratory Physiology', 'Ventilation, gas exchange, oxygen and carbon dioxide transport. Respiratory regulation, pulmonary function tests and adaptation to altitude.', 2, NULL, NULL, NULL, 'cmsqtq99x000jwwk51tnfs88r', '2026-08-13T01:12:51.368Z', '2026-08-13T01:12:51.368Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqaib000pwwk5kpuh90q2', 'Metabolism of Nutrients', 'Carbohydrate, lipid and protein metabolism. Energy balance, gluconeogenesis, lipogenesis and amino acid metabolism in domestic animals.', 2, NULL, NULL, NULL, 'cmsqtq99x000jwwk51tnfs88r', '2026-08-13T01:12:51.635Z', '2026-08-13T01:12:51.635Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqapp000qwwk5fcqdtfqc', 'Cardiovascular Physiology', 'Cardiac cycle, heart rate regulation, cardiac output, blood pressure and haemodynamics. Coronary circulation and cardiac electrophysiology.', 3, NULL, NULL, NULL, 'cmsqtq99x000jwwk51tnfs88r', '2026-08-13T01:12:51.901Z', '2026-08-13T01:12:51.901Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqax2000rwwk57qnwb8on', 'Renal Physiology', 'Glomerular filtration, tubular reabsorption and secretion. Counter-current mechanism, urine formation and concentration. Renal regulation of acid-base balance.', 3, NULL, NULL, NULL, 'cmsqtq99x000jwwk51tnfs88r', '2026-08-13T01:12:52.166Z', '2026-08-13T01:12:52.166Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqb4g000swwk5ne8kaohk', 'Urinary System Function', 'Bladder function, micturition reflex, clearance tests and renal physiology across species.', 3, NULL, NULL, NULL, 'cmsqtq99x000jwwk51tnfs88r', '2026-08-13T01:12:52.432Z', '2026-08-13T01:12:52.432Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqbbs000twwk526slcp8e', 'Reproductive Physiology – Male', 'Spermatogenesis, testicular function, hormonal regulation and semen characteristics. Puberty, sexual behaviour and seasonal breeding patterns.', 4, NULL, NULL, NULL, 'cmsqtq99x000jwwk51tnfs88r', '2026-08-13T01:12:52.696Z', '2026-08-13T01:12:52.696Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqbj5000uwwk5jjuon1l4', 'Reproductive Physiology – Female', 'Oogenesis, oestrus cycle, hormonal regulation and follicular dynamics. Pregnancy recognition, placental function and parturition.', 4, NULL, NULL, NULL, 'cmsqtq99x000jwwk51tnfs88r', '2026-08-13T01:12:52.961Z', '2026-08-13T01:12:52.961Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqbqi000vwwk5wrnse2yj', 'Lactation Physiology', 'Mammary gland development, lactogenesis, milk composition and ejection reflex. Hormonal control of lactation and milking physiology.', 4, NULL, NULL, NULL, 'cmsqtq99x000jwwk51tnfs88r', '2026-08-13T01:12:53.226Z', '2026-08-13T01:12:53.226Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqbxu000wwwk5ryy3r95d', 'Endocrine Physiology', 'Hypothalamic-pituitary axis, thyroid, adrenal and pancreatic hormones. Hormonal regulation of metabolism, growth and reproduction.', 4, NULL, NULL, NULL, 'cmsqtq99x000jwwk51tnfs88r', '2026-08-13T01:12:53.490Z', '2026-08-13T01:12:53.490Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqc5h000xwwk5q8ie7dg2', 'Biomolecules – Structure and Function', 'Carbohydrates, lipids, proteins and nucleic acids. Structure-function relationships, conformational changes and biochemical classification.', 5, NULL, NULL, NULL, 'cmsqtq99x000jwwk51tnfs88r', '2026-08-13T01:12:53.765Z', '2026-08-13T01:12:53.765Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqccu000ywwk5g0mizs6v', 'Enzymes and Enzyme Kinetics', 'Enzyme classification, mechanisms of catalysis, Michaelis-Menten kinetics. Enzyme regulation, allosteric control and clinical enzymology.', 5, NULL, NULL, NULL, 'cmsqtq99x000jwwk51tnfs88r', '2026-08-13T01:12:54.030Z', '2026-08-13T01:12:54.030Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqcka000zwwk5vl405z89', 'Biochemical Techniques', 'Spectrophotometry, chromatography, electrophoresis and centrifugation. Clinical biochemistry laboratory methods and quality control.', 5, NULL, NULL, NULL, 'cmsqtq99x000jwwk51tnfs88r', '2026-08-13T01:12:54.298Z', '2026-08-13T01:12:54.298Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqcrn0010wwk5rvh9p847', 'Carbohydrate Metabolism', 'Glycolysis, TCA cycle, oxidative phosphorylation and pentose phosphate pathway. Gluconeogenesis, glycogen metabolism and blood glucose regulation.', 6, NULL, NULL, NULL, 'cmsqtq99x000jwwk51tnfs88r', '2026-08-13T01:12:54.563Z', '2026-08-13T01:12:54.563Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqcz10011wwk565709zrw', 'Lipid Metabolism', 'Beta-oxidation, ketogenesis, lipogenesis and cholesterol metabolism. Fatty acid synthesis, phospholipid metabolism and lipoproteins.', 6, NULL, NULL, NULL, 'cmsqtq99x000jwwk51tnfs88r', '2026-08-13T01:12:54.829Z', '2026-08-13T01:12:54.829Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqd6f0012wwk5r3snnw3t', 'Protein and Amino Acid Metabolism', 'Protein synthesis, transamination, deamination and urea cycle. Nitrogen balance and amino acid catabolism.', 6, NULL, NULL, NULL, 'cmsqtq99x000jwwk51tnfs88r', '2026-08-13T01:12:55.095Z', '2026-08-13T01:12:55.095Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqdl60014wwk53n6ebnl0', 'Livestock Breeds – Cattle', 'Indigenous and exotic cattle breeds, their characteristics and adaptability. Bos indicus vs Bos taurus breeds and crossbreeding programs.', 1, NULL, NULL, NULL, 'cmsqtqddt0013wwk52y6r1e9r', '2026-08-13T01:12:55.626Z', '2026-08-13T01:12:55.626Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqdsl0015wwk5ed4tdmow', 'Livestock Breeds – Buffalo, Sheep and Goat', 'Major buffalo breeds, sheep breeds for wool and meat, goat breeds for dairy and fibre. Breed identification and selection criteria.', 1, NULL, NULL, NULL, 'cmsqtqddt0013wwk52y6r1e9r', '2026-08-13T01:12:55.893Z', '2026-08-13T01:12:55.893Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqdzx0016wwk5hrc6jadv', 'General Management Practices', 'Daily care routines, feeding schedules, health monitoring and record keeping. Basic principles of livestock husbandry.', 1, NULL, NULL, NULL, 'cmsqtqddt0013wwk52y6r1e9r', '2026-08-13T01:12:56.157Z', '2026-08-13T01:12:56.157Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqe7a0017wwk5c1zo1ufz', 'Housing and Shelter Design', 'Types of animal housing, layout planning, ventilation, lighting and temperature control. Space requirements for different species.', 2, NULL, NULL, NULL, 'cmsqtqddt0013wwk52y6r1e9r', '2026-08-13T01:12:56.422Z', '2026-08-13T01:12:56.422Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqeen0018wwk5prr6poqo', 'Animal Handling and Restraint', 'Safe handling techniques, physical restraint methods, use of squeeze chutes and tilt tables. Low-stress handling and animal welfare.', 2, NULL, NULL, NULL, 'cmsqtqddt0013wwk52y6r1e9r', '2026-08-13T01:12:56.687Z', '2026-08-13T01:12:56.687Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqelz0019wwk5otc287aq', 'Farm Infrastructure', 'Feed storage, water supply, waste management and fencing. Farm planning and infrastructure development for different livestock operations.', 2, NULL, NULL, NULL, 'cmsqtqddt0013wwk52y6r1e9r', '2026-08-13T01:12:56.951Z', '2026-08-13T01:12:56.951Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqetc001awwk5sjclyqjr', 'Cattle Management', 'Feeding management, milking routines, breeding management and record keeping for dairy and beef cattle. Seasonal management practices.', 3, NULL, NULL, NULL, 'cmsqtqddt0013wwk52y6r1e9r', '2026-08-13T01:12:57.216Z', '2026-08-13T01:12:57.216Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqf0p001bwwk5i9y8vxvc', 'Buffalo Management', 'Buffalo-specific husbandry practices, wallowing, heat stress management and dairy buffalo production systems.', 3, NULL, NULL, NULL, 'cmsqtqddt0013wwk52y6r1e9r', '2026-08-13T01:12:57.481Z', '2026-08-13T01:12:57.481Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqf83001cwwk5n44uj7gi', 'Health Management in Cattle', 'Vaccination schedules, common disease prevention, biosecurity measures and quarantine protocols for cattle operations.', 3, NULL, NULL, NULL, 'cmsqtqddt0013wwk52y6r1e9r', '2026-08-13T01:12:57.747Z', '2026-08-13T01:12:57.747Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqffk001dwwk52hwv3h66', 'Sheep and Goat Management', 'Feeding, housing, breeding and health care for small ruminants. Flock management, shearing and kid/lamb rearing practices.', 4, NULL, NULL, NULL, 'cmsqtqddt0013wwk52y6r1e9r', '2026-08-13T01:12:58.016Z', '2026-08-13T01:12:58.016Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqfmy001ewwk5bg85dw0n', 'Poultry Management', 'Broiler and layer management, housing systems, feeding programs and environmental control in poultry production.', 4, NULL, NULL, NULL, 'cmsqtqddt0013wwk52y6r1e9r', '2026-08-13T01:12:58.282Z', '2026-08-13T01:12:58.282Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqful001fwwk5z36k2br8', 'Swine Management', 'Pig production systems, feeding, breeding and farrowing management. Environmental requirements and health programs for swine.', 4, NULL, NULL, NULL, 'cmsqtqddt0013wwk52y6r1e9r', '2026-08-13T01:12:58.557Z', '2026-08-13T01:12:58.557Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqg9k001hwwk5ueax8pyp', 'Fundamentals of Extension Education', 'Definition, objectives and philosophy of extension education. History of agricultural extension, extension principles and teaching-learning process.', 1, NULL, NULL, NULL, 'cmsqtqg23001gwwk55wd4sqdc', '2026-08-13T01:12:59.096Z', '2026-08-13T01:12:59.096Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqggx001iwwk5214f6qon', 'Rural Sociology and Development', 'Rural social structure, social groups, community development and leadership. Role of extension in rural livelihood improvement.', 1, NULL, NULL, NULL, 'cmsqtqg23001gwwk55wd4sqdc', '2026-08-13T01:12:59.361Z', '2026-08-13T01:12:59.361Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqgo9001jwwk5futx7gx7', 'Extension Philosophy and Approaches', 'Farmers first approach, participatory rural appraisal and community-driven development. Adult education principles and extension methodologies.', 1, NULL, NULL, NULL, 'cmsqtqg23001gwwk55wd4sqdc', '2026-08-13T01:12:59.625Z', '2026-08-13T01:12:59.625Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqgvo001kwwk502bsyd8l', 'Extension Programme Planning', 'Needs assessment, programme development, implementation and evaluation. Logical framework approach and result-based management in extension.', 2, NULL, NULL, NULL, 'cmsqtqg23001gwwk55wd4sqdc', '2026-08-13T01:12:59.892Z', '2026-08-13T01:12:59.892Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqh31001lwwk5ptc37tqy', 'Extension Teaching Methods', 'Individual, group and mass methods of extension teaching. Farm demonstrations, training, exhibitions, farm visits and field days.', 2, NULL, NULL, NULL, 'cmsqtqg23001gwwk55wd4sqdc', '2026-08-13T01:13:00.157Z', '2026-08-13T01:13:00.157Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqhad001mwwk595e139qq', 'Training and Capacity Building', 'Training need assessment, training design, delivery and evaluation. Capacity building of farmers, extension workers and rural youth.', 2, NULL, NULL, NULL, 'cmsqtqg23001gwwk55wd4sqdc', '2026-08-13T01:13:00.421Z', '2026-08-13T01:13:00.421Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqhhq001nwwk5lt3azgsq', 'Communication in Extension', 'Communication models, barriers and strategies. Verbal, non-verbal and visual communication in extension. Interpersonal communication skills.', 3, NULL, NULL, NULL, 'cmsqtqg23001gwwk55wd4sqdc', '2026-08-13T01:13:00.687Z', '2026-08-13T01:13:00.687Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqhp8001owwk5qv44l47f', 'Mass Media and ICT in Extension', 'Role of radio, television, print media and social media in extension. ICT-based extension – mobile apps, e-learning and digital platforms.', 3, NULL, NULL, NULL, 'cmsqtqg23001gwwk55wd4sqdc', '2026-08-13T01:13:00.956Z', '2026-08-13T01:13:00.956Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqhwl001pwwk5dudl8ayp', 'Audio-Visual Aids and Presentation', 'Use of charts, models, posters, video and multimedia in extension. Effective presentation and public speaking skills for extension professionals.', 3, NULL, NULL, NULL, 'cmsqtqg23001gwwk55wd4sqdc', '2026-08-13T01:13:01.221Z', '2026-08-13T01:13:01.221Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqi3x001qwwk56z3rvbki', 'Livestock Entrepreneurship', 'Entrepreneurship development, business planning and feasibility studies. Value chain analysis and market linkages for livestock products.', 4, NULL, NULL, NULL, 'cmsqtqg23001gwwk55wd4sqdc', '2026-08-13T01:13:01.485Z', '2026-08-13T01:13:01.485Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqibb001rwwk5k2f59pqk', 'Self-Help Groups and Cooperatives', 'Formation and management of self-help groups, cooperatives and farmer producer organisations. Microfinance and credit access for livestock farmers.', 4, NULL, NULL, NULL, 'cmsqtqg23001gwwk55wd4sqdc', '2026-08-13T01:13:01.751Z', '2026-08-13T01:13:01.751Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqiiq001swwk5vlkll120', 'Extension Programme Evaluation', 'Impact assessment, monitoring and evaluation methods. Cost-benefit analysis of extension programmes and outcome measurement.', 4, NULL, NULL, NULL, 'cmsqtqg23001gwwk55wd4sqdc', '2026-08-13T01:13:02.018Z', '2026-08-13T01:13:02.018Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqixj001uwwk5y5s2z7q7', 'Introduction to Genetics', 'Mendelian laws of inheritance, gene concept, multiple alleles and gene interactions. Chromosomal basis of inheritance and chromosomal aberrations.', 1, NULL, NULL, NULL, 'cmsqtqiq5001twwk52n8iwbdt', '2026-08-13T01:13:02.551Z', '2026-08-13T01:13:02.551Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqj4w001vwwk5wzhfwmgd', 'Quantitative Genetics', 'Polygenic inheritance, additive and non-additive genetic variance. Heritability, repeatability and genetic correlation concepts.', 1, NULL, NULL, NULL, 'cmsqtqiq5001twwk52n8iwbdt', '2026-08-13T01:13:02.816Z', '2026-08-13T01:13:02.816Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqjcb001wwwk55kztilfe', 'Population Genetics', 'Hardy-Weinberg equilibrium, gene and genotypic frequencies. Factors changing gene frequencies – selection, drift, mutation and migration.', 1, NULL, NULL, NULL, 'cmsqtqiq5001twwk52n8iwbdt', '2026-08-13T01:13:03.083Z', '2026-08-13T01:13:03.083Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqjjs001xwwk5s523ejv9', 'Principles of Animal Breeding', 'Selection methods – mass, progeny, sib and combined selection. Selection intensity, genetic progress and breeding value estimation.', 2, NULL, NULL, NULL, 'cmsqtqiq5001twwk52n8iwbdt', '2026-08-13T01:13:03.352Z', '2026-08-13T01:13:03.352Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqjr5001ywwk5hpsxp17z', 'Mating Systems', 'Inbreeding, linebreeding, outcrossing and crossbreeding. Heterosis and its exploitation in livestock improvement programs.', 2, NULL, NULL, NULL, 'cmsqtqiq5001twwk52n8iwbdt', '2026-08-13T01:13:03.617Z', '2026-08-13T01:13:03.617Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqjyj001zwwk517k5zmlw', 'Breeding Programmes', 'Centralized recording, genetic evaluation and national breeding programmes. Sire selection, dam selection and breeding value prediction.', 2, NULL, NULL, NULL, 'cmsqtqiq5001twwk52n8iwbdt', '2026-08-13T01:13:03.883Z', '2026-08-13T01:13:03.883Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqk5x0020wwk5x0oy3jes', 'Reproductive Technologies in Breeding', 'Artificial insemination, embryo transfer, multiple ovulation and embryo transfer (MOET). In-vitro fertilisation and embryo biotechnology.', 3, NULL, NULL, NULL, 'cmsqtqiq5001twwk52n8iwbdt', '2026-08-13T01:13:04.149Z', '2026-08-13T01:13:04.149Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqkdc0021wwk5ouqhmmbk', 'Molecular Genetics and Markers', 'DNA markers, RFLP, microsatellites, SNP and QTL mapping. Marker-assisted selection and genomic selection in livestock.', 3, NULL, NULL, NULL, 'cmsqtqiq5001twwk52n8iwbdt', '2026-08-13T01:13:04.416Z', '2026-08-13T01:13:04.416Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqkko0022wwk5o8aw5vzz', 'Genomic Selection', 'Genome-wide association studies, genomic estimated breeding values. Reference populations, SNP chips and implementation of genomic selection.', 3, NULL, NULL, NULL, 'cmsqtqiq5001twwk52n8iwbdt', '2026-08-13T01:13:04.680Z', '2026-08-13T01:13:04.680Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqks20023wwk5zz2e19u0', 'Breeding for Production Traits', 'Selection for milk production, growth rate, wool production and reproductive efficiency. Index selection and multi-trait selection.', 4, NULL, NULL, NULL, 'cmsqtqiq5001twwk52n8iwbdt', '2026-08-13T01:13:04.946Z', '2026-08-13T01:13:04.946Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqkzf0024wwk55vw54nai', 'Breeding for Disease Resistance', 'Genetic resistance to diseases, breeding for immune competence. Genetic disorders and their control in livestock populations.', 4, NULL, NULL, NULL, 'cmsqtqiq5001twwk52n8iwbdt', '2026-08-13T01:13:05.211Z', '2026-08-13T01:13:05.211Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtql6t0025wwk5g9iw9vfc', 'Conservation of Animal Genetic Resources', 'Breed conservation strategies, in-situ and ex-situ conservation. Genetic diversity assessment and management of endangered breeds.', 4, NULL, NULL, NULL, 'cmsqtqiq5001twwk52n8iwbdt', '2026-08-13T01:13:05.477Z', '2026-08-13T01:13:05.477Z');
