INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqww7003qwwk5b0zd3fs4', 'Semen Collection and Evaluation', 'Semen collection methods – artificial vagina, electro-ejaculation and massage. Semen evaluation – motility, morphology, concentration and viability.', 2, NULL, NULL, NULL, 'cmsqtqw2n003mwwk5ed5k9a1u', '2026-08-13T01:13:20.647Z', '2026-08-13T01:13:20.647Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqx3k003rwwk5m26nico2', 'Artificial Insemination Techniques', 'AI equipment, insemination methods, timing and technique. Deep uterine and cervical insemination. AI in cattle, buffalo, sheep and goats.', 2, NULL, NULL, NULL, 'cmsqtqw2n003mwwk5ed5k9a1u', '2026-08-13T01:13:20.912Z', '2026-08-13T01:13:20.912Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqxay003swwk5djnzyvzq', 'Semen Processing and Storage', 'Semen dilution, extender composition, cooling and freezing protocols. Liquid nitrogen storage and straw technology.', 2, NULL, NULL, NULL, 'cmsqtqw2n003mwwk5ed5k9a1u', '2026-08-13T01:13:21.178Z', '2026-08-13T01:13:21.178Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqxic003twwk5ibvkovik', 'Pregnancy Diagnosis', 'Rectal palpation, ultrasonography, hormonal tests and blood tests for pregnancy diagnosis. Timing and accuracy of different methods.', 3, NULL, NULL, NULL, 'cmsqtqw2n003mwwk5ed5k9a1u', '2026-08-13T01:13:21.444Z', '2026-08-13T01:13:21.444Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqxpq003uwwk5uyt4ihkx', 'Gestation Period and Fetal Development', 'Duration of gestation across species, fetal membranes, placental types and fetal development milestones.', 3, NULL, NULL, NULL, 'cmsqtqw2n003mwwk5ed5k9a1u', '2026-08-13T01:13:21.710Z', '2026-08-13T01:13:21.710Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqxx3003vwwk5hbj23xel', 'Parturition', 'Signs of parturition, stages of labour, fetal membranes and placental expulsion. Dystocia recognition, assisted delivery and obstetric procedures.', 3, NULL, NULL, NULL, 'cmsqtqw2n003mwwk5ed5k9a1u', '2026-08-13T01:13:21.975Z', '2026-08-13T01:13:21.975Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqy4h003wwwk534wjt7sa', 'Reproductive Disorders – Female', 'Ovarian cysts, silent heat, anestrus, metritis and pyometra. Uterine prolapse, vaginal prolapse and their management.', 4, NULL, NULL, NULL, 'cmsqtqw2n003mwwk5ed5k9a1u', '2026-08-13T01:13:22.241Z', '2026-08-13T01:13:22.241Z');
INSERT INTO "Chapter" ("id", "title", "content", "unitNumber", "courseCode", "creditHours", "type", "subjectId", "createdAt", "updatedAt") VALUES ('cmsqtqybu003xwwk5t50umgr5', 'Reproductive Disorders – Male', 'Cryptorchidism, hypoplasia, seminal vesiculitis and orchitis. Breeding soundness examination of males.', 4, NULL, NULL, NULL, 'cmsqtqw2n003mwwk5ed5k9a1u', '2026-08-13T01:13:22.506Z', '2026-08-13T01:13:22.506Z');
