INSERT INTO "Question" ("id", "text", "options", "correctAnswer", "marks", "explanation", "mockTestId", "createdAt", "updatedAt") VALUES ('cmsqtt19b00dtwwk52nrv9n7q', 'How many cervical vertebrae does a horse have?', '["5","7","9","12"]', 1, 2, 'Horses, like most mammals, have 7 cervical vertebrae.', 'cmsqtt11q00dswwk58gtwd735', '2026-08-13T01:14:59.615Z', '2026-08-13T01:14:59.615Z');
INSERT INTO "Question" ("id", "text", "options", "correctAnswer", "marks", "explanation", "mockTestId", "createdAt", "updatedAt") VALUES ('cmsqtt1h400duwwk5yiz77olh', 'Which bone is commonly called the kneecap?', '["Humerus","Femur","Patella","Tibia"]', 2, 2, 'The patella is the sesamoid bone found within the quadriceps tendon, commonly known as the kneecap.', 'cmsqtt11q00dswwk58gtwd735', '2026-08-13T01:14:59.896Z', '2026-08-13T01:14:59.896Z');
INSERT INTO "Question" ("id", "text", "options", "correctAnswer", "marks", "explanation", "mockTestId", "createdAt", "updatedAt") VALUES ('cmsqtt1oi00dvwwk59azkzrb3', 'What type of joint is the elbow?', '["Ball and socket","Hinge joint","Pivot joint","Gliding joint"]', 1, 2, 'The elbow is a hinge joint allowing flexion and extension.', 'cmsqtt11q00dswwk58gtwd735', '2026-08-13T01:15:00.162Z', '2026-08-13T01:15:00.162Z');
INSERT INTO "Question" ("id", "text", "options", "correctAnswer", "marks", "explanation", "mockTestId", "createdAt", "updatedAt") VALUES ('cmsqtt1vz00dwwwk5ttwx3s04', 'Which is the largest bone in the body of a cow?', '["Femur","Tibia","Pelvis","Humerus"]', 0, 2, 'The femur is the largest and strongest bone in the body of most domestic animals.', 'cmsqtt11q00dswwk58gtwd735', '2026-08-13T01:15:00.432Z', '2026-08-13T01:15:00.432Z');
INSERT INTO "Question" ("id", "text", "options", "correctAnswer", "marks", "explanation", "mockTestId", "createdAt", "updatedAt") VALUES ('cmsqtt23e00dxwwk5cukjngst', 'The atlas is the _____ cervical vertebra.', '["1st","2nd","3rd","7th"]', 0, 2, 'The atlas (C1) is the first cervical vertebra that articulates with the skull.', 'cmsqtt11q00dswwk58gtwd735', '2026-08-13T01:15:00.698Z', '2026-08-13T01:15:00.698Z');
INSERT INTO "Question" ("id", "text", "options", "correctAnswer", "marks", "explanation", "mockTestId", "createdAt", "updatedAt") VALUES ('cmsudpm7a0007agk58mttddvz', 'Veterinary Officer (VO/VS): Normal heart rate range in cattle?', '["40-80 bpm","100-140 bpm","150-200 bpm","20-40 bpm"]', 0, 2, 'Adult cattle HR is approximately 60-80 bpm.', 'cmsudplzl0006agk5so1fhb2e', '2026-08-15T12:55:30.982Z', '2026-08-15T12:55:30.982Z');
INSERT INTO "Question" ("id", "text", "options", "correctAnswer", "marks", "explanation", "mockTestId", "createdAt", "updatedAt") VALUES ('cmsudpmf10008agk5fp0y9du3', 'Veterinary Officer (VO/VS): FMD is controlled using which type of vaccine?', '["Live attenuated","Inactivated trivalent","Subunit","Toxoid"]', 1, 2, 'Inactivated (killed) trivalent vaccine is used for FMD.', 'cmsudplzl0006agk5so1fhb2e', '2026-08-15T12:55:31.262Z', '2026-08-15T12:55:31.262Z');
INSERT INTO "Question" ("id", "text", "options", "correctAnswer", "marks", "explanation", "mockTestId", "createdAt", "updatedAt") VALUES ('cmsudpmmd0009agk5i32q5u1s', 'Veterinary Officer (VO/VS): Ruminants possess how many stomach compartments?', '["1","2","3","4"]', 3, 2, 'Ruminants have four compartments: rumen, reticulum, omasum, abomasum.', 'cmsudplzl0006agk5so1fhb2e', '2026-08-15T12:55:31.525Z', '2026-08-15T12:55:31.525Z');
INSERT INTO "Question" ("id", "text", "options", "correctAnswer", "marks", "explanation", "mockTestId", "createdAt", "updatedAt") VALUES ('cmsudpmtn000aagk550nueu2i', 'Veterinary Officer (VO/VS): Deficiency of which vitamin causes night blindness?', '["Vitamin B12","Vitamin C","Vitamin A","Vitamin D"]', 2, 2, 'Vitamin A deficiency leads to night blindness.', 'cmsudplzl0006agk5so1fhb2e', '2026-08-15T12:55:31.787Z', '2026-08-15T12:55:31.787Z');
INSERT INTO "Question" ("id", "text", "options", "correctAnswer", "marks", "explanation", "mockTestId", "createdAt", "updatedAt") VALUES ('cmsudpn0w000bagk5ksyz3lep', 'Veterinary Officer (VO/VS): The abbreviation "I/V" refers to which route?', '["Intravenous","Intramuscular","Subcutaneous","Oral"]', 0, 2, 'I/V = intravenous.', 'cmsudplzl0006agk5so1fhb2e', '2026-08-15T12:55:32.048Z', '2026-08-15T12:55:32.048Z');
