INSERT INTO "Question" ("id", "text", "options", "correctAnswer", "marks", "explanation", "mockTestId", "createdAt", "updatedAt") VALUES ('cmsvg6g6p001nn0k5em91ha9d', 'Which of the following is the primary site of nutrient absorption in the exam preparation?', '["Rumen","Abomasum","Small intestine","Large intestine"]', 2, 1, 'The small intestine (especially jejunum) is the main site of digestion and absorption of nutrients.', 'cmsvg6fs4001mn0k57r1iyhp5', '2026-08-16T06:52:21.745Z', '2026-08-16T06:52:21.745Z');
INSERT INTO "Question" ("id", "text", "options", "correctAnswer", "marks", "explanation", "mockTestId", "createdAt", "updatedAt") VALUES ('cmsvg6g6p001on0k5bbitdswu', 'The normal heart rate range in a resting adult dairy animal is:', '["30–50 bpm","60–80 bpm","120–160 bpm","200–240 bpm"]', 1, 1, 'Adult cattle typically have a resting heart rate of about 60–80 beats per minute.', 'cmsvg6fs4001mn0k57r1iyhp5', '2026-08-16T06:52:21.745Z', '2026-08-16T06:52:21.745Z');
INSERT INTO "Question" ("id", "text", "options", "correctAnswer", "marks", "explanation", "mockTestId", "createdAt", "updatedAt") VALUES ('cmsvg6g6p001pn0k5azh2w65k', 'Which vitamin deficiency most commonly causes night blindness in livestock?', '["Vitamin C","Vitamin A","Vitamin D","Vitamin K"]', 1, 1, 'Vitamin A (retinol) deficiency leads to impaired rod-cell function and night blindness.', 'cmsvg6fs4001mn0k57r1iyhp5', '2026-08-16T06:52:21.745Z', '2026-08-16T06:52:21.745Z');
