INSERT INTO "FarmGuide" ("id", "category", "title", "summary", "content", "published", "order", "createdAt", "updatedAt") VALUES ('cmsvgdipt000cask55uh8qdhz', 'DAIRY', 'Scientific Dairy Farming Basics', 'Housing, feeding and milking practices for profitable dairy.', '<p>Provide clean, ventilated housing and a balanced ration (16-18% protein for milch animals). Milking should follow strict hygiene with teat dipping post-milking.</p>', TRUE, 0, '2026-08-16T06:57:51.617Z', '2026-08-16T06:57:51.617Z');
INSERT INTO "FarmGuide" ("id", "category", "title", "summary", "content", "published", "order", "createdAt", "updatedAt") VALUES ('cmsvgdixf000dask5ls7hxl3p', 'GOAT', 'Goat Farming for Beginners', 'Housing, breeding and health management for goats.', '<p>Goats need draft-free housing and browse. Vaccinate for PPR and deworm every 2-3 months.</p>', TRUE, 0, '2026-08-16T06:57:51.891Z', '2026-08-16T06:57:51.891Z');
INSERT INTO "FarmGuide" ("id", "category", "title", "summary", "content", "published", "order", "createdAt", "updatedAt") VALUES ('cmsvgdjhx000eask5e85nx4la', 'SHEEP', 'Sheep Rearing Essentials', 'Flock management and common diseases.', '<p>Sheep thrive on grazing; shelter from rain and regular deworming are key.</p>', TRUE, 0, '2026-08-16T06:57:52.629Z', '2026-08-16T06:57:52.629Z');
INSERT INTO "FarmGuide" ("id", "category", "title", "summary", "content", "published", "order", "createdAt", "updatedAt") VALUES ('cmsvgdjp6000fask55sxktgjl', 'POULTRY', 'Profitable Poultry (Layers & Broilers)', 'Housing, feeding and disease control for birds.', '<p>Biosecurity and phase feeding (starter-grower-finisher) maximise profits.</p>', TRUE, 0, '2026-08-16T06:57:52.890Z', '2026-08-16T06:57:52.890Z');
INSERT INTO "FarmGuide" ("id", "category", "title", "summary", "content", "published", "order", "createdAt", "updatedAt") VALUES ('cmsvgdjwf000gask5y2d5a8bi', 'PIG', 'Pig Farming Fundamentals', 'Housing, feeding and breeding of pigs.', '<p>Pigs need shaded, clean pens and high-energy feed. Prevent swine fever via vaccination.</p>', TRUE, 0, '2026-08-16T06:57:53.151Z', '2026-08-16T06:57:53.151Z');
INSERT INTO "FarmGuide" ("id", "category", "title", "summary", "content", "published", "order", "createdAt", "updatedAt") VALUES ('cmsvgdk3p000hask5i5vzuc9f', 'SCIENTIFIC', 'Principles of Scientific Livestock Farming', 'Record keeping, biosecurity and economics.', '<p>Maintain herd records, follow a vaccination calendar and calculate feed-to-production ratio for profitability.</p>', TRUE, 0, '2026-08-16T06:57:53.413Z', '2026-08-16T06:57:53.413Z');
