INSERT INTO "ProjectReport" ("id", "title", "farmType", "summary", "demoContent", "fullContent", "price", "published", "order", "createdAt", "updatedAt") VALUES ('cmsvgdkb4000iask5ml8r2j80', 'Dairy Farming Project Report (10 Cattle)', 'DAIRY', 'Investment, recurring costs, milk yield and payback for a 10-cattle dairy unit.', '<h3>Sample: Executive Summary</h3><p>This demo shows the report format. Purchase to unlock the full financial model with month-wise cash flow, feed cost breakdown and sensitivity analysis.</p>', '<h3>Full Report</h3><p><b>Investment:</b> Rs. 5-8 Lakh (shed, animals, equipment).</p><p><b>Recurring:</b> Feed Rs. 2.5L/yr, labour Rs. 1.2L/yr.</p><p><b>Revenue:</b> ~Rs. 3.5L/yr from 60 L/day milk.</p><p><b>Payback:</b> 2-3 years. Detailed month-wise cash flow, sensitivity and risk notes included after purchase.</p>', 199, TRUE, 0, '2026-08-16T06:57:53.680Z', '2026-08-16T06:57:53.680Z');
